public with sharing class ExchangeRateClient {

    public class ExchangeRateException extends Exception {}

    private static final Pattern CODE_PATTERN = Pattern.compile('^[A-Z]{3}$');

    public static Map<String, Decimal> getRates(String baseCurrency, Set<String> quoteCurrencies) {
        if (quoteCurrencies == null || quoteCurrencies.isEmpty()) {
            throw new ExchangeRateException('Quote currency set must not be null or empty.');
        }

        String normalizedBase = normalizeCode(baseCurrency);
        if (!isValidCode(normalizedBase)) {
            throw new ExchangeRateException('Invalid base currency code: ' + baseCurrency);
        }

        Set<String> normalizedQuotes = new Set<String>();
        for (String q : quoteCurrencies) {
            String normalized = normalizeCode(q);
            if (!isValidCode(normalized)) {
                throw new ExchangeRateException('Invalid quote currency code: ' + q);
            }
            normalizedQuotes.add(normalized);
        }

        String symbolsParam = String.join(new List<String>(normalizedQuotes), ',');

        String endpoint = 'callout:FB_Exchange_Rates/v1/latest?base='
            + EncodingUtil.urlEncode(normalizedBase, 'UTF-8')
            + '&symbols=' + EncodingUtil.urlEncode(symbolsParam, 'UTF-8');

        HttpRequest req = new HttpRequest();
        req.setEndpoint(endpoint);
        req.setMethod('GET');
        req.setHeader('Accept', 'application/json');

        Http http = new Http();
        HttpResponse res = http.send(req);

        if (res.getStatusCode() == 503) {
            res = http.send(req);
        }

        if (res.getStatusCode() != 200) {
            throw new ExchangeRateException('Exchange rate API returned HTTP status code ' + res.getStatusCode());
        }

        Map<String, Object> parsed;
        try {
            parsed = (Map<String, Object>) JSON.deserializeUntyped(res.getBody());
        } catch (Exception e) {
            throw new ExchangeRateException('Unable to parse exchange rate response: ' + e.getMessage());
        }

        if (parsed == null || !parsed.containsKey('rates') || !(parsed.get('rates') instanceof Map<String, Object>)) {
            throw new ExchangeRateException('Unable to parse exchange rate response: missing rates object.');
        }

        Map<String, Object> ratesObj = (Map<String, Object>) parsed.get('rates');

        Map<String, Decimal> result = new Map<String, Decimal>();
        for (String quote : normalizedQuotes) {
            if (!ratesObj.containsKey(quote) || ratesObj.get(quote) == null) {
                throw new ExchangeRateException('No rate returned for requested currency: ' + quote);
            }
            Object rateVal = ratesObj.get(quote);
            Decimal rate;
            try {
                rate = (Decimal) rateVal;
            } catch (Exception e) {
                throw new ExchangeRateException('Invalid rate value for currency: ' + quote);
            }
            result.put(quote, rate);
        }

        return result;
    }

    private static String normalizeCode(String code) {
        if (code == null) {
            return null;
        }
        return code.trim().toUpperCase();
    }

    private static Boolean isValidCode(String code) {
        if (code == null) {
            return false;
        }
        return CODE_PATTERN.matcher(code).matches();
    }
}
