/**
 * RecordSearchService
 *
 * Generic, security-aware record search utility used by the admin "record finder"
 * Lightning component. Runs a single, dynamically built but injection-safe SOQL
 * query honouring the running user's object/field level security and record
 * sharing.
 */
public with sharing class RecordSearchService {

    public class SearchException extends Exception {}

    public static List<SObject> search(String objectApiName,
                                        List<String> fields,
                                        Map<String, Object> filters,
                                        String orderByField,
                                        Integer maxRows) {

        // ---- maxRows ----
        if (maxRows == null || maxRows < 1 || maxRows > 200) {
            throw new SearchException('maxRows must be between 1 and 200.');
        }

        // ---- fields ----
        if (fields == null || fields.isEmpty()) {
            throw new SearchException('At least one field must be requested.');
        }

        // ---- object ----
        if (String.isBlank(objectApiName)) {
            throw new SearchException('An object API name must be provided.');
        }

        Schema.SObjectType sObjType = resolveSObjectType(objectApiName);
        if (sObjType == null) {
            throw new SearchException('Object "' + objectApiName + '" does not exist.');
        }

        Schema.DescribeSObjectResult objDescribe = sObjType.getDescribe();
        if (!objDescribe.isAccessible()) {
            throw new SearchException('You do not have access to object "' + objDescribe.getName() + '".');
        }

        // ---- field map (case-insensitive) ----
        Map<String, Schema.SObjectField> fieldMap = objDescribe.fields.getMap();

        // ---- validate & resolve SELECT fields ----
        List<String> selectFieldApiNames = new List<String>();
        Set<String> seenLower = new Set<String>();
        for (String rawField : fields) {
            if (String.isBlank(rawField)) {
                throw new SearchException('A field name cannot be blank.');
            }
            Schema.DescribeFieldResult fieldDescribe = resolveField(fieldMap, rawField, objDescribe.getName());
            if (!fieldDescribe.isAccessible()) {
                throw new SearchException('You do not have access to field "' + fieldDescribe.getName() + '".');
            }
            String lowerName = fieldDescribe.getName().toLowerCase();
            if (!lowerName.equals('id') && !seenLower.contains(lowerName)) {
                seenLower.add(lowerName);
                selectFieldApiNames.add(fieldDescribe.getName());
            }
        }

        // ---- validate filters & build WHERE clause ----
        List<String> whereConditions = new List<String>();
        Map<String, Object> bindMap = new Map<String, Object>();
        Integer bindIndex = 0;

        if (filters != null && !filters.isEmpty()) {
            for (String rawFilterField : filters.keySet()) {
                if (String.isBlank(rawFilterField)) {
                    throw new SearchException('A filter field name cannot be blank.');
                }
                Schema.DescribeFieldResult fieldDescribe = resolveField(fieldMap, rawFilterField, objDescribe.getName());
                if (!fieldDescribe.isAccessible()) {
                    throw new SearchException('You do not have access to field "' + fieldDescribe.getName() + '".');
                }
                if (!fieldDescribe.isFilterable()) {
                    throw new SearchException('Field "' + fieldDescribe.getName() + '" cannot be filtered.');
                }

                Object value = filters.get(rawFilterField);
                String apiName = fieldDescribe.getName();

                if (value == null) {
                    whereConditions.add(apiName + ' = null');
                } else {
                    String bindName = 'v' + bindIndex;
                    bindIndex++;
                    bindMap.put(bindName, value);
                    whereConditions.add(apiName + ' = :' + bindName);
                }
            }
        }

        // ---- validate ORDER BY ----
        String orderByApiName = null;
        if (String.isNotBlank(orderByField)) {
            Schema.DescribeFieldResult fieldDescribe = resolveField(fieldMap, orderByField, objDescribe.getName());
            if (!fieldDescribe.isAccessible()) {
                throw new SearchException('You do not have access to field "' + fieldDescribe.getName() + '".');
            }
            if (!fieldDescribe.isSortable()) {
                throw new SearchException('Field "' + fieldDescribe.getName() + '" cannot be sorted.');
            }
            orderByApiName = fieldDescribe.getName();
        }

        // ---- build query ----
        List<String> selectList = new List<String>{ 'Id' };
        selectList.addAll(selectFieldApiNames);

        String query = 'SELECT ' + String.join(selectList, ', ') +
                        ' FROM ' + objDescribe.getName();

        if (!whereConditions.isEmpty()) {
            query += ' WHERE ' + String.join(whereConditions, ' AND ');
        }

        if (orderByApiName != null) {
            query += ' ORDER BY ' + orderByApiName + ' ASC';
        }

        query += ' LIMIT ' + String.valueOf(maxRows);

        try {
            return Database.queryWithBinds(query, bindMap, AccessLevel.USER_MODE);
        } catch (Exception e) {
            throw new SearchException('Unable to execute search: ' + e.getMessage());
        }
    }

    private static Schema.SObjectType resolveSObjectType(String objectApiName) {
        Map<String, Schema.SObjectType> globalDescribe = Schema.getGlobalDescribe();
        Schema.SObjectType result = globalDescribe.get(objectApiName);
        if (result != null) {
            return result;
        }
        String lower = objectApiName.toLowerCase();
        for (String key : globalDescribe.keySet()) {
            if (key.toLowerCase() == lower) {
                return globalDescribe.get(key);
            }
        }
        return null;
    }

    private static Schema.DescribeFieldResult resolveField(Map<String, Schema.SObjectField> fieldMap,
                                                             String fieldApiName,
                                                             String objectLabel) {
        Schema.SObjectField field = fieldMap.get(fieldApiName);
        if (field == null) {
            String lower = fieldApiName.toLowerCase();
            for (String key : fieldMap.keySet()) {
                if (key.toLowerCase() == lower) {
                    field = fieldMap.get(key);
                    break;
                }
            }
        }
        if (field == null) {
            throw new SearchException('Field "' + fieldApiName + '" does not exist on object "' + objectLabel + '".');
        }
        return field.getDescribe();
    }
}
