public class OrderPayloadParser {

    public class PayloadException extends Exception {}

    public class Order {
        public String orderNumber;
        public Date orderDate;
        public String currencyCode;
        public String customerEmail;
        public List<Line> lines = new List<Line>();
        public Decimal total;
    }

    public class Line {
        public String sku;
        public Integer quantity;
        public Decimal unitPrice;
        public Decimal discount;
        public Decimal lineTotal;
    }

    public static Order parse(String body) {
        if (String.isBlank(body)) {
            throw new PayloadException('Body is null or blank.');
        }

        Object parsed;
        try {
            parsed = JSON.deserializeUntyped(body);
        } catch (Exception e) {
            throw new PayloadException('Invalid JSON: ' + e.getMessage());
        }

        if (!(parsed instanceof Map<String, Object>)) {
            throw new PayloadException('Payload is not a JSON object.');
        }
        Map<String, Object> root = (Map<String, Object>) parsed;

        Order order = new Order();

        // number
        Object numberObj = root.get('number');
        if (!(numberObj instanceof String) || String.isBlank((String) numberObj)) {
            throw new PayloadException('Missing or blank order number.');
        }
        order.orderNumber = (String) numberObj;

        // date
        Object dateObj = root.get('date');
        if (dateObj != null) {
            if (!(dateObj instanceof String)) {
                throw new PayloadException('Invalid date format.');
            }
            try {
                order.orderDate = Date.valueOf((String) dateObj);
            } catch (Exception e) {
                throw new PayloadException('Invalid date format: ' + e.getMessage());
            }
        }

        // currency
        Object currencyObj = root.get('currency');
        if (currencyObj != null) {
            if (!(currencyObj instanceof String)) {
                throw new PayloadException('Invalid currency code.');
            }
            order.currencyCode = (String) currencyObj;
        }

        // customer
        Object customerObj = root.get('customer');
        if (customerObj != null) {
            if (!(customerObj instanceof Map<String, Object>)) {
                throw new PayloadException('Invalid customer object.');
            }
            Map<String, Object> customerMap = (Map<String, Object>) customerObj;
            Object emailObj = customerMap.get('email');
            if (emailObj != null) {
                if (!(emailObj instanceof String)) {
                    throw new PayloadException('Invalid customer email.');
                }
                order.customerEmail = (String) emailObj;
            }
        }

        // lines
        Object linesObj = root.get('lines');
        List<Line> lineList = new List<Line>();
        Decimal total = 0;

        if (linesObj != null) {
            if (!(linesObj instanceof List<Object>)) {
                throw new PayloadException('Invalid lines array.');
            }
            for (Object lineRaw : (List<Object>) linesObj) {
                if (!(lineRaw instanceof Map<String, Object>)) {
                    throw new PayloadException('Invalid line entry.');
                }
                Map<String, Object> lineMap = (Map<String, Object>) lineRaw;
                Line line = new Line();

                Object skuObj = lineMap.get('sku');
                if (!(skuObj instanceof String) || String.isBlank((String) skuObj)) {
                    throw new PayloadException('Missing sku in line.');
                }
                line.sku = (String) skuObj;

                Integer qty = toInteger(lineMap.get('quantity'));
                if (qty == null || qty <= 0) {
                    throw new PayloadException('Missing or non-positive quantity in line.');
                }
                line.quantity = qty;

                Decimal price = toDecimal(lineMap.get('unitPrice'));
                if (price == null || price < 0) {
                    throw new PayloadException('Missing or negative unitPrice in line.');
                }
                line.unitPrice = price;

                Decimal discount = toDecimal(lineMap.get('discount'));
                if (discount == null) {
                    discount = 0;
                }
                line.discount = discount;

                Decimal rawTotal = line.quantity * line.unitPrice * (1 - line.discount);
                line.lineTotal = rawTotal.setScale(2, System.RoundingMode.HALF_UP);

                total += line.lineTotal;
                lineList.add(line);
            }
        }

        order.lines = lineList;
        order.total = total.setScale(2, System.RoundingMode.HALF_UP);

        return order;
    }

    public static String toAcknowledgement(Order order) {
        Map<String, Object> ack = new Map<String, Object>();
        ack.put('number', order.orderNumber);
        ack.put('status', 'RECEIVED');
        ack.put('lineCount', order.lines == null ? 0 : order.lines.size());
        ack.put('total', order.total);
        return JSON.serialize(ack);
    }

    private static Integer toInteger(Object obj) {
        if (obj == null) {
            return null;
        }
        if (obj instanceof Integer) {
            return (Integer) obj;
        }
        if (obj instanceof Long) {
            return Integer.valueOf((Long) obj);
        }
        if (obj instanceof Decimal) {
            Decimal d = (Decimal) obj;
            if (d.scale() > 0 && d != d.setScale(0)) {
                return null;
            }
            return d.intValue();
        }
        if (obj instanceof Double) {
            Double dbl = (Double) obj;
            if (Math.abs(dbl - Math.round(dbl)) > 0.0000001) {
                return null;
            }
            return Integer.valueOf(Math.round(dbl).intValue());
        }
        return null;
    }

    private static Decimal toDecimal(Object obj) {
        if (obj == null) {
            return null;
        }
        if (obj instanceof Decimal) {
            return (Decimal) obj;
        }
        if (obj instanceof Integer) {
            return Decimal.valueOf((Integer) obj);
        }
        if (obj instanceof Long) {
            return Decimal.valueOf((Long) obj);
        }
        if (obj instanceof Double) {
            return Decimal.valueOf(String.valueOf((Double) obj));
        }
        return null;
    }
}
