public with sharing class LeadImportService {

    public class ImportResult {
        public Integer successCount;
        public List<Id> insertedIds;
        public Map<Integer, String> errorsByIndex;

        public ImportResult() {
            this.successCount = 0;
            this.insertedIds = new List<Id>();
            this.errorsByIndex = new Map<Integer, String>();
        }
    }

    public static ImportResult importLeads(List<Lead> leads) {
        ImportResult result = new ImportResult();

        if (leads == null || leads.isEmpty()) {
            return result;
        }

        List<Lead> leadsToInsert = new List<Lead>();
        List<Integer> originalIndexes = new List<Integer>();
        Set<String> seenEmails = new Set<String>();

        for (Integer i = 0; i < leads.size(); i++) {
            Lead ld = leads[i];

            String normalizedEmail = null;
            if (ld.Email != null) {
                String trimmed = ld.Email.trim();
                if (!String.isBlank(trimmed)) {
                    normalizedEmail = trimmed.toLowerCase();
                }
            }

            if (normalizedEmail != null) {
                if (seenEmails.contains(normalizedEmail)) {
                    result.errorsByIndex.put(i, 'Duplicate email in import: ' + normalizedEmail);
                    continue;
                }
                seenEmails.add(normalizedEmail);
            }

            if (String.isBlank(ld.LeadSource)) {
                ld.LeadSource = 'Web';
            }

            leadsToInsert.add(ld);
            originalIndexes.add(i);
        }

        if (!leadsToInsert.isEmpty()) {
            Database.SaveResult[] saveResults = Database.insert(leadsToInsert, false);

            for (Integer j = 0; j < saveResults.size(); j++) {
                Database.SaveResult sr = saveResults[j];
                Integer originalIndex = originalIndexes[j];

                if (sr.isSuccess()) {
                    result.successCount++;
                } else {
                    List<String> messages = new List<String>();
                    for (Database.Error err : sr.getErrors()) {
                        messages.add(err.getMessage());
                    }
                    result.errorsByIndex.put(originalIndex, String.join(messages, '; '));
                }
            }

            for (Integer k = 0; k < leads.size(); k++) {
                if (!result.errorsByIndex.containsKey(k)) {
                    Lead ld = leads[k];
                    if (ld.Id != null) {
                        result.insertedIds.add(ld.Id);
                    }
                }
            }
        }

        return result;
    }
}
