public with sharing class PicklistService {

    public class PicklistServiceException extends Exception {}

    public class Option {
        public String value;
        public String label;
        public Boolean isDefault;

        public Option(String value, String label, Boolean isDefault) {
            this.value = value;
            this.label = label;
            this.isDefault = isDefault;
        }
    }

    public static List<Option> activeOptions(String objectApiName, String fieldApiName) {
        if (String.isBlank(objectApiName) || String.isBlank(fieldApiName)) {
            throw new PicklistServiceException('Object API name and field API name must be provided.');
        }

        Schema.SObjectType sobjType = Schema.getGlobalDescribe().get(objectApiName.trim().toLowerCase());
        if (sobjType == null) {
            throw new PicklistServiceException('Object "' + objectApiName + '" does not exist.');
        }

        Schema.DescribeSObjectResult objDescribe = sobjType.getDescribe();
        Map<String, Schema.SObjectField> fieldMap = objDescribe.fields.getMap();

        Schema.SObjectField fieldToken = fieldMap.get(fieldApiName.trim().toLowerCase());
        if (fieldToken == null) {
            throw new PicklistServiceException('Field "' + fieldApiName + '" does not exist on object "' + objectApiName + '".');
        }

        Schema.DescribeFieldResult fieldDescribe = fieldToken.getDescribe();
        Schema.DisplayType fieldType = fieldDescribe.getType();

        if (fieldType != Schema.DisplayType.PICKLIST && fieldType != Schema.DisplayType.MULTIPICKLIST) {
            throw new PicklistServiceException('Field "' + fieldApiName + '" on object "' + objectApiName + '" is not a picklist or multi-select picklist.');
        }

        List<Option> result = new List<Option>();
        List<Schema.PicklistEntry> entries = fieldDescribe.getPicklistValues();

        for (Schema.PicklistEntry entry : entries) {
            if (entry.isActive()) {
                result.add(new Option(entry.getValue(), entry.getLabel(), entry.isDefaultValue()));
            }
        }

        return result;
    }
}
