public with sharing class OpportunityPipelineHandler {

    /**
     * Entry point called from OpportunityTrigger for every DML event
     * (insert, update, delete, undelete). Pass whichever list(s) are
     * relevant for the event; either may be null.
     */
    public static void handle(List<Opportunity> newOpps, List<Opportunity> oldOpps) {
        Set<Id> accountIds = new Set<Id>();

        if (newOpps != null) {
            for (Opportunity o : newOpps) {
                if (o.AccountId != null) {
                    accountIds.add(o.AccountId);
                }
            }
        }

        if (oldOpps != null) {
            for (Opportunity o : oldOpps) {
                if (o.AccountId != null) {
                    accountIds.add(o.AccountId);
                }
            }
        }

        if (accountIds.isEmpty()) {
            return;
        }

        recalculate(accountIds);
    }

    /**
     * Recomputes the open-pipeline amount and open-opportunity count for the
     * given set of Account Ids, and updates the Account records only when the
     * stored values actually differ from the freshly computed ones. The
     * "only update when changed" guard is what keeps this safe in combination
     * with the existing AccountTrigger (which re-saves open Opportunities on
     * every Account update): once the aggregates are stable, no further
     * Account update is issued, so the Account -> Opportunity -> Account
     * update cycle terminates.
     */
    private static void recalculate(Set<Id> accountIds) {
        Map<Id, Decimal> pipelineByAccount = new Map<Id, Decimal>();
        Map<Id, Integer> countByAccount = new Map<Id, Integer>();

        for (AggregateResult ar : [
            SELECT AccountId acctId, SUM(Amount) totalAmount, COUNT(Id) totalCount
            FROM Opportunity
            WHERE AccountId IN :accountIds AND IsClosed = false
            GROUP BY AccountId
        ]) {
            Id acctId = (Id) ar.get('acctId');
            Decimal totalAmount = (Decimal) ar.get('totalAmount');
            Integer totalCount = (Integer) ar.get('totalCount');

            pipelineByAccount.put(acctId, totalAmount == null ? 0 : totalAmount);
            countByAccount.put(acctId, totalCount == null ? 0 : totalCount);
        }

        List<Account> accountsToUpdate = new List<Account>();

        for (Account acc : [
            SELECT Id, FB_Open_Pipeline__c, FB_Open_Opportunities__c
            FROM Account
            WHERE Id IN :accountIds
        ]) {
            Decimal newPipeline = pipelineByAccount.containsKey(acc.Id)
                ? pipelineByAccount.get(acc.Id)
                : 0;
            Integer newCount = countByAccount.containsKey(acc.Id)
                ? countByAccount.get(acc.Id)
                : 0;

            Decimal currentPipeline = acc.FB_Open_Pipeline__c == null
                ? 0
                : acc.FB_Open_Pipeline__c;
            Integer currentCount = acc.FB_Open_Opportunities__c == null
                ? 0
                : acc.FB_Open_Opportunities__c.intValue();

            if (currentPipeline != newPipeline || currentCount != newCount) {
                acc.FB_Open_Pipeline__c = newPipeline;
                acc.FB_Open_Opportunities__c = newCount;
                accountsToUpdate.add(acc);
            }
        }

        if (!accountsToUpdate.isEmpty()) {
            update accountsToUpdate;
        }
    }
}
