public inherited sharing class CaseEscalationService {

    public class EscalationException extends Exception {}

    public static void escalate(Set<Id> caseIds, String reason) {
        if (String.isBlank(reason)) {
            throw new EscalationException('Reason must not be blank.');
        }

        if (caseIds == null || caseIds.isEmpty()) {
            return;
        }

        List<Case> cases = CasesSelector.newInstance().selectById(caseIds);

        fflib_ISObjectUnitOfWork uow = Application.UnitOfWork.newInstance();

        Boolean hasWork = false;

        for (Case c : cases) {
            if (c.Status == 'Closed' || c.IsEscalated) {
                continue;
            }

            c.IsEscalated = true;
            c.Priority = 'High';

            Task t = new Task();
            t.Subject = 'Escalated: ' + reason;
            t.WhatId = c.Id;
            t.OwnerId = c.OwnerId;
            t.ActivityDate = Date.today().addDays(1);
            t.Priority = 'High';

            uow.registerDirty(c);
            uow.registerNew(t);

            hasWork = true;
        }

        if (hasWork) {
            uow.commitWork();
        }
    }
}
