public with sharing class CasePriorityHandler {

    /**
     * For any new Case whose Account has Rating = 'Hot', set Priority to 'High'.
     * All other cases keep whatever Priority they already have.
     *
     * Note: we query Accounts once, outside the loop, instead of querying
     * per-Case. Querying inside a loop would exceed the 100-SOQL-queries-per-
     * transaction limit when the ERP integration inserts batches of up to
     * 200 Cases at once, causing the whole insert to fail. This single bulk
     * query approach is just as easy to follow and is safe for both single
     * Email-to-Case inserts and large batch inserts.
     */
    public static void setPriorityForHotAccounts(List<Case> newCases) {
        // Collect the distinct Account Ids we need to check (skip cases with no account).
        Set<Id> accountIds = new Set<Id>();
        for (Case c : newCases) {
            if (c.AccountId != null) {
                accountIds.add(c.AccountId);
            }
        }

        if (accountIds.isEmpty()) {
            return;
        }

        // Single query for all the accounts we care about.
        Map<Id, Account> accountsById = new Map<Id, Account>(
            [SELECT Id, Rating FROM Account WHERE Id IN :accountIds]
        );

        // Apply the rule: Hot account -> High priority.
        for (Case c : newCases) {
            if (c.AccountId == null) {
                continue;
            }

            Account acc = accountsById.get(c.AccountId);
            if (acc != null && acc.Rating == 'Hot') {
                c.Priority = 'High';
            }
        }
    }
}
