```apex
/**
 * Sends newly created Accounts to the ERP, one HTTP request per Account.
 *
 * Because an Apex transaction can insert up to 200 Accounts at once (the
 * marketplace integration) but callouts are not allowed synchronously in a
 * trigger, this class processes the accounts asynchronously via a
 * self-chaining Queueable: each execution sends exactly one callout for one
 * account and then re-enqueues itself for the remaining ones.
 */
public with sharing class ErpCustomerSync implements Queueable, Database.AllowsCallouts {

    private static final String ENDPOINT = 'callout:ERP/api/customers';

    private List<CustomerPayload> pending;

    public ErpCustomerSync(List<CustomerPayload> pending) {
        this.pending = pending;
    }

    public void execute(QueueableContext qc) {
        if (pending == null || pending.isEmpty()) {
            return;
        }

        // Take the first account off the queue and send it on its own.
        CustomerPayload current = pending.remove(0);
        sendCustomer(current);

        // Chain the rest, one callout per job execution.
        // Apex test context only allows one level of job chaining, so we
        // skip the recursive enqueue while running tests to avoid a
        // System.LimitException; tests should invoke execute() directly
        // for each item or run with Test.stopTest() per step.
        if (!pending.isEmpty() && !Test.isRunningTest()) {
            System.enqueueJob(new ErpCustomerSync(pending));
        }
    }

    private void sendCustomer(CustomerPayload customer) {
        HttpRequest req = new HttpRequest();
        req.setEndpoint(ENDPOINT);
        req.setMethod('POST');
        req.setHeader('Content-Type', 'application/json');
        req.setBody(JSON.serialize(new List<CustomerPayload>{ customer }));

        Http http = new Http();
        // ERP responds 202 Accepted on success. Error handling / retries
        // are explicitly out of scope for this ticket.
        http.send(req);
    }

    public class CustomerPayload {
        public String salesforceId;
        public String name;
        public String country;

        public CustomerPayload(Id accountId, String accountName, String billingCountry) {
            this.salesforceId = accountId == null ? null : String.valueOf(accountId);
            this.name = accountName;
            this.country = String.isBlank(billingCountry) ? null : billingCountry;
        }
    }
}
