/**
 * After-update trigger on Case.
 * Detects cases that transition from not-closed to closed and, if they have
 * a Contact, schedules an async survey-task creation job.
 *
 * All qualifying Case Ids from the trigger batch are passed to a single
 * CaseSurveyJob instance so that bulk closes (list view mass actions,
 * nightly API cleanup of up to 200 records, etc.) never exceed the
 * System.enqueueJob governor limit.
 */
trigger CaseTrigger on Case (after update) {

    if (Trigger.isAfter && Trigger.isUpdate) {

        Set<Id> newlyClosedCaseIdsWithContact = new Set<Id>();

        for (Case c : Trigger.new) {
            Case oldCase = Trigger.oldMap.get(c.Id);

            Boolean becameClosed = (oldCase.IsClosed == false) && (c.IsClosed == true);

            if (becameClosed && c.ContactId != null) {
                newlyClosedCaseIdsWithContact.add(c.Id);
            }
        }

        if (!newlyClosedCaseIdsWithContact.isEmpty()) {
            System.enqueueJob(new CaseSurveyJob(newlyClosedCaseIdsWithContact));
        }
    }
}
