import { LightningElement } from 'lwc';
import searchContacts from '@salesforce/apex/ContactController.searchContacts';

const DEBOUNCE_MS = 300;
const MIN_LENGTH = 2;

export default class ContactSearch extends LightningElement {
    contacts = [];
    error;

    debounceTimer;
    requestSequence = 0;
    isConnected = false;

    connectedCallback() {
        this.isConnected = true;
    }

    disconnectedCallback() {
        this.isConnected = false;
        if (this.debounceTimer) {
            clearTimeout(this.debounceTimer);
            this.debounceTimer = undefined;
        }
    }

    handleChange(event) {
        const rawValue = event.target.value;
        const trimmedValue = (rawValue || '').trim();

        // Cancel any pending debounce timer
        if (this.debounceTimer) {
            clearTimeout(this.debounceTimer);
            this.debounceTimer = undefined;
        }

        // Bump sequence so any in-flight responses become stale
        this.requestSequence++;

        if (trimmedValue.length < MIN_LENGTH) {
            this.contacts = [];
            this.error = undefined;
            return;
        }

        const currentSequence = this.requestSequence;

        this.debounceTimer = setTimeout(() => {
            this.debounceTimer = undefined;
            this.executeSearch(trimmedValue, currentSequence);
        }, DEBOUNCE_MS);
    }

    executeSearch(searchTerm, sequence) {
        searchContacts({ searchTerm })
            .then((result) => {
                if (!this.isConnected) {
                    return;
                }
                if (sequence !== this.requestSequence) {
                    // A newer request has superseded this one
                    return;
                }
                this.contacts = result;
                this.error = undefined;
            })
            .catch((error) => {
                if (!this.isConnected) {
                    return;
                }
                if (sequence !== this.requestSequence) {
                    return;
                }
                this.error = error?.body?.message || 'An unknown error occurred';
                this.contacts = [];
            });
    }
}
