import { LightningElement, api } from 'lwc';
import getOpenOpportunities from '@salesforce/apex/OpportunityController.getOpenOpportunities';

export default class OpenOpportunities extends LightningElement {
    @api recordId;

    isLoading = false;
    opportunities = [];
    hasError = false;
    errorMessage = '';
    hasLoaded = false;

    connectedCallback() {
        if (!this.hasLoaded) {
            this.hasLoaded = true;
            this.loadOpportunities();
        }
    }

    loadOpportunities() {
        this.isLoading = true;
        this.hasError = false;
        this.errorMessage = '';

        getOpenOpportunities({ accountId: this.recordId })
            .then((result) => {
                this.opportunities = result;
                this.hasError = false;
            })
            .catch((error) => {
                this.hasError = true;
                this.opportunities = [];
                this.errorMessage =
                    (error && error.body && error.body.message) ||
                    'An unknown error occurred';
            })
            .finally(() => {
                this.isLoading = false;
            });
    }

    get hasOpportunities() {
        return !this.hasError && this.opportunities && this.opportunities.length > 0;
    }

    get isEmpty() {
        return !this.hasError && (!this.opportunities || this.opportunities.length === 0);
    }

    handleRetry() {
        this.loadOpportunities();
    }
}
