import { LightningElement, api } from 'lwc';

export default class OrderLinesPanel extends LightningElement {
    /** Array of { key, productName, quantity } */
    @api lines = [];

    showError = false;

    get editors() {
        return this.template.querySelectorAll('c-line-item-editor');
    }

    handleReset() {
        this.editors.forEach((editor) => editor.reset());
        this.showError = false;
    }

    handleSubmit() {
        const editors = Array.from(this.editors);

        // Validate every editor, even after one fails, so all errors show.
        let allValid = true;
        editors.forEach((editor) => {
            const isValid = editor.validate();
            if (!isValid) {
                allValid = false;
            }
        });

        if (!allValid) {
            this.showError = true;
            return;
        }

        this.showError = false;

        const lines = editors.map((editor) => editor.getValue());

        this.dispatchEvent(
            new CustomEvent('submit', {
                detail: { lines }
            })
        );
    }
}
