import { LightningElement } from 'lwc';
import getQueueStats from '@salesforce/apex/QueueController.getQueueStats';

const POLL_INTERVAL_MS = 60000;

export default class QueueMonitor extends LightningElement {
    waiting;
    longestWaitMinutes;
    errorMessage;
    hasData = false;

    intervalId;
    isRequestInFlight = false;

    boundVisibilityHandler;

    connectedCallback() {
        this.boundVisibilityHandler = this.handleVisibilityChange.bind(this);
        document.addEventListener('visibilitychange', this.boundVisibilityHandler);

        this.startPolling();
    }

    disconnectedCallback() {
        this.stopPolling();

        if (this.boundVisibilityHandler) {
            document.removeEventListener('visibilitychange', this.boundVisibilityHandler);
            this.boundVisibilityHandler = undefined;
        }
    }

    startPolling() {
        // Ensure only one polling loop is active at a time.
        this.stopPolling();

        if (document.visibilityState !== 'hidden') {
            this.loadStats();
        }

        this.intervalId = window.setInterval(() => {
            if (document.visibilityState === 'hidden') {
                return;
            }
            this.loadStats();
        }, POLL_INTERVAL_MS);
    }

    stopPolling() {
        if (this.intervalId) {
            window.clearInterval(this.intervalId);
            this.intervalId = undefined;
        }
    }

    handleVisibilityChange() {
        if (document.visibilityState === 'hidden') {
            return;
        }
        // Became visible again: load immediately and keep polling on the same cadence.
        this.loadStats();
    }

    loadStats() {
        if (this.isRequestInFlight) {
            return;
        }
        this.isRequestInFlight = true;

        getQueueStats()
            .then((result) => {
                this.waiting = result.waiting;
                this.longestWaitMinutes = result.longestWaitMinutes;
                this.hasData = true;
                this.errorMessage = undefined;
            })
            .catch((error) => {
                this.errorMessage =
                    (error && error.body && error.body.message) ||
                    'An unknown error occurred.';
            })
            .finally(() => {
                this.isRequestInFlight = false;
            });
    }
}
