import { LightningElement, api } from 'lwc';

const ACTIVATING_KEYS = ['ArrowDown', 'ArrowUp', 'Home', 'End', 'Enter', ' '];

export default class StatusListbox extends LightningElement {
    @api label;
    @api options = [];

    _value = '';
    _explicitActive = null;

    uid = `status-listbox-${Math.random().toString(36).substring(2, 11)}`;

    @api
    get value() {
        return this._value;
    }
    set value(val) {
        this._value = val;
        // Parent changed the selection: active option follows it.
        this._explicitActive = null;
    }

    toId(value) {
        return `${this.uid}-${String(value).replace(/[^a-zA-Z0-9_-]/g, '_')}`;
    }

    get activeOptionValue() {
        if (this._explicitActive !== null) {
            return this._explicitActive;
        }
        if (this._value) {
            return this._value;
        }
        return this.options && this.options.length ? this.options[0].value : null;
    }

    get activeDescendantId() {
        const activeValue = this.activeOptionValue;
        return activeValue !== null && activeValue !== undefined ? this.toId(activeValue) : null;
    }

    get normalizedOptions() {
        return (this.options || []).map((option) => ({
            value: option.value,
            label: option.label,
            id: this.toId(option.value),
            ariaSelected: option.value === this._value ? 'true' : 'false'
        }));
    }

    handleKeyDown(event) {
        const key = event.key;
        if (!ACTIVATING_KEYS.includes(key)) {
            return;
        }

        const values = (this.options || []).map((o) => o.value);
        if (values.length === 0) {
            return;
        }

        let currentIndex = values.indexOf(this.activeOptionValue);
        if (currentIndex === -1) {
            currentIndex = 0;
        }

        event.preventDefault();

        switch (key) {
            case 'ArrowDown':
                if (currentIndex < values.length - 1) {
                    this._explicitActive = values[currentIndex + 1];
                }
                break;
            case 'ArrowUp':
                if (currentIndex > 0) {
                    this._explicitActive = values[currentIndex - 1];
                }
                break;
            case 'Home':
                this._explicitActive = values[0];
                break;
            case 'End':
                this._explicitActive = values[values.length - 1];
                break;
            case 'Enter':
            case ' ':
                this.selectOption(this.activeOptionValue);
                break;
            default:
                break;
        }
    }

    handleOptionClick(event) {
        const value = event.currentTarget.dataset.value;
        this.selectOption(value);
    }

    selectOption(value) {
        if (value === undefined || value === null) {
            return;
        }

        this._explicitActive = value;

        if (value === this._value) {
            return;
        }

        this._value = value;
        this.dispatchEvent(
            new CustomEvent('change', {
                detail: { value }
            })
        );
    }
}
