        return this._heading ? this._heading.toUpperCase() : '';
    }

    @api
    get tasks() {
        return this._tasks;
    }
    set tasks(value) {
        this._tasks = value;
        this.items = (value || []).map((task) => ({ ...task }));
    }

    get remaining() {
        return this.items.filter((task) => !task.done).length;
    }

    handleLabelChange(event) {
        this.newLabel = event.detail.value;
    }

    handleAdd() {
        const trimmed = (this.newLabel || '').trim();
        if (!trimmed) {
            return;
        }
        this.items = [
            ...this.items,
            { id: `new-${this.nextId++}`, label: trimmed, done: false }
        ];
        this.newLabel = '';
        this.dispatchEvent(new CustomEvent('taskadded', { detail: { label: trimmed } }));
    }

    handleToggle(event) {
        const id = event.target.dataset.id;
        this.items = this.items.map((t) =>
            t.id === id ? { ...t, done: !t.done } : t
        );
    }
}
