/**
 * Service class that synchronizes a Contact's current employer (Organization Account)
 * using NPSP Affiliations. Relies on NPSP's standard Affiliation TDTM logic to:
 *   - demote any previous primary Affiliation to Former, non-primary, with an EndDate of today
 *   - update Contact.npsp__Primary_Affiliation__c to point to the new Organization
 *
 * This class performs at most 1 SOQL query and 1 DML statement regardless of
 * the size of the input map (bulk safe up to governor limits for the batch size
 * passed in, e.g. 200 contacts).
 */
public without sharing class EmployerService {

    public static void setCurrentEmployers(Map<Id, Id> employerByContactId) {
        if (employerByContactId == null || employerByContactId.isEmpty()) {
            return;
        }

        Set<Id> contactIds = employerByContactId.keySet();

        // Single SOQL query: pull each contact's current primary affiliation lookup
        // so we can skip contacts whose primary employer is already correct.
        Map<Id, Contact> contactsById = new Map<Id, Contact>([
            SELECT Id, npsp__Primary_Affiliation__c
            FROM Contact
            WHERE Id IN :contactIds
        ]);

        List<npe5__Affiliation__c> affiliationsToInsert = new List<npe5__Affiliation__c>();

        for (Id contactId : contactIds) {
            Id orgId = employerByContactId.get(contactId);
            if (orgId == null) {
                continue;
            }

            Contact con = contactsById.get(contactId);
            if (con == null) {
                continue;
            }

            // Already the primary employer - nothing to do, avoid duplicate affiliation.
            if (con.npsp__Primary_Affiliation__c == orgId) {
                continue;
            }

            // Creating a new Current, Primary affiliation triggers NPSP's TDTM logic,
            // which automatically:
            //  - sets any previously primary affiliation for this contact to
            //    Status = 'Former', Primary__c = false, EndDate__c = today
            //  - updates Contact.npsp__Primary_Affiliation__c to this organization
            affiliationsToInsert.add(new npe5__Affiliation__c(
                npe5__Contact__c       = contactId,
                npe5__Organization__c  = orgId,
