/**
 * Routes one-off web gifts through NPSP's Batch Data Import (BDI) engine so that
 * NPSP's own contact matching, household creation and donation processing rules
 * are applied, and the staged npsp__DataImport__c records remain in the org as
 * an audit trail of what was imported.
 */
public with sharing class GiftImportService {

    public class WebGift {
        public String firstName;
        public String lastName;
        public String email;        // the donor's personal email
        public Decimal amount;
        public Date giftDate;
    }

    public class ImportResult {
        public Boolean success;
        public Id contactId;        // the matched or created contact
        public Id opportunityId;    // the created donation
        public String errorMessage; // NPSP's failure information when success is false
    }

    public static List<ImportResult> importGifts(List<WebGift> gifts) {
        List<ImportResult> results = new List<ImportResult>();

        if (gifts == null || gifts.isEmpty()) {
            return results;
        }

        // Stage one NPSP Data Import record per gift, preserving input order.
        List<npsp__DataImport__c> diRecords = new List<npsp__DataImport__c>();
        for (WebGift gift : gifts) {
            npsp__DataImport__c di = new npsp__DataImport__c();
            di.npsp__Contact1_Firstname__c = gift.firstName;
            di.npsp__Contact1_Lastname__c = gift.lastName;
            di.npsp__Contact1_Personal_Email__c = gift.email;
            di.npsp__Donation_Amount__c = gift.amount;
            di.npsp__Donation_Date__c = gift.giftDate;
            di.npsp__Donation_Donor__c = 'Contact1';
            diRecords.add(di);
        }

        insert diRecords;

        // Keep the input order by Id for mapping results back later.
        List<Id> orderedIds = new List<Id>();
        for (npsp__DataImport__c di : diRecords) {
            orderedIds.add(di.Id);
        }

        // Use the org's existing Data Import settings (matching rules, etc.).
        npsp__Data_Import_Settings__c settings = npsp.UTIL_CustomSettingsFacade.getDataImportSettings();

        // Process synchronously, in this transaction. Rows that fail to import
        // do not throw; NPSP marks them Failed with FailureInformation populated.
        npsp.BDI_DataImport_API.processDataImportRecords(settings, diRecords, false);

        // Re-query to read back the fields NPSP wrote during processing.
        Map<Id, npsp__DataImport__c> processedById = new Map<Id, npsp__DataImport__c>(
            [SELECT Id, npsp__Status__c, npsp__Contact1Imported__c,
                    npsp__DonationImported__c, npsp__FailureInformation__c
             FROM npsp__DataImport__c
             WHERE Id IN :orderedIds]
        );

        for (Id diId : orderedIds) {
            npsp__DataImport__c processed = processedById.get(diId);
            ImportResult result = new ImportResult();

            if (processed == null) {
                result.success = false;
                result.errorMessage = 'NPSP Data Import record could not be found after processing.';
            } else {
                Boolean imported = processed.npsp__Status__c == 'Imported';
                result.success = imported;
                result.contactId = processed.npsp__Contact1Imported__c;
                result.opportunityId = processed.npsp__DonationImported__c;
                result.errorMessage = imported ? null : processed.npsp__FailureInformation__c;
            }

            results.add(result);
        }

        return results;
    }
}
