/**
 * Service class for allocating Opportunity amounts across General Accounting Units (GAUs)
 * by percentage, replacing any existing GAU Allocations on the Opportunity.
 *
 * Allocations are written using npsp__Percent__c only (Amount is left for NPSP's own
 * allocation logic to calculate), so that when the Opportunity Amount is later changed,
 * NPSP's standard allocation trigger handlers recompute npsp__Amount__c on each
 * allocation automatically, keeping the split proportionally correct.
 */
public with sharing class GauAllocationService {

    public class AllocationException extends Exception {}

    public static List<npsp__Allocation__c> allocateByPercent(Id opportunityId, Map<Id, Decimal> percentByGauId) {

        // ---------- Validation (must happen before any data is changed) ----------

        if (opportunityId == null) {
            throw new AllocationException('Opportunity Id is required.');
        }

        if (percentByGauId == null || percentByGauId.isEmpty()) {
            throw new AllocationException('percentByGauId must not be null or empty.');
        }

        Decimal totalPercent = 0;
        for (Id gauId : percentByGauId.keySet()) {
            if (gauId == null) {
                throw new AllocationException('GAU Id keys must not be null.');
            }
            Decimal pct = percentByGauId.get(gauId);
            if (pct == null || pct <= 0) {
                throw new AllocationException('Percentage for GAU ' + gauId + ' must be greater than 0.');
            }
            totalPercent += pct;
        }

        if (totalPercent > 100) {
            throw new AllocationException('Total allocation percentage cannot exceed 100%. Current total: ' + totalPercent);
        }

        Map<Id, npsp__General_Accounting_Unit__c> gauById = new Map<Id, npsp__General_Accounting_Unit__c>(
            [SELECT Id, Name, npsp__Active__c
             FROM npsp__General_Accounting_Unit__c
             WHERE Id IN :percentByGauId.keySet()]
        );

        for (Id gauId : percentByGauId.keySet()) {
            npsp__General_Accounting_Unit__c gau = gauById.get(gauId);
            if (gau == null) {
                throw new AllocationException('General Accounting Unit not found: ' + gauId);
            }
            if (gau.npsp__Active__c != true) {
                throw new AllocationException('General Accounting Unit is inactive: ' + gau.Name + ' (' + gauId + ')');
            }
        }

        // ---------- Build the new allocation records (not yet inserted) ----------

        List<npsp__Allocation__c> newAllocations = new List<npsp__Allocation__c>();
        for (Id gauId : percentByGauId.keySet()) {
            npsp__Allocation__c allo = new npsp__Allocation__c();
            allo.npsp__Opportunity__c = opportunityId;
            allo.npsp__General_Accounting_Unit__c = gauId;
            allo.npsp__Percent__c = percentByGauId.get(gauId);
            newAllocations.add(allo);
        }

        // ---------- Replace existing allocations and insert new ones ----------

        List<npsp__Allocation__c> existingAllocations = [
            SELECT Id
            FROM npsp__Allocation__c
            WHERE npsp__Opportunity__c = :opportunityId
        ];

        Savepoint sp = Database.setSavepoint();
        try {
            if (!existingAllocations.isEmpty()) {
                delete existingAllocations;
            }
            insert newAllocations;
        } catch (Exception ex) {
            Database.rollback(sp);
            throw new AllocationException('Failed to replace GAU allocations: ' + ex.getMessage());
        }

        return newAllocations;
    }
}
