/**
 * Service class for recording gifts (donations) that have already been received,
 * crediting them to the correct NPSP Household Account, Contact Role(s), and Payment.
 */
public with sharing class GiftService {

    private static final String STAGE_CLOSED_WON = 'Closed Won';
    private static final String ROLE_DONOR = 'Donor';
    private static final String ROLE_HOUSEHOLD_MEMBER = 'Household Member';

    /**
     * Records a Closed Won gift from the given contact, on the given date, for the given amount.
     * Returns the Id of the created Opportunity.
     */
    public static Id recordGift(Id contactId, Decimal amount, Date giftDate) {
        if (contactId == null) {
            throw new IllegalArgumentException('Contact Id is required.');
        }
        if (amount == null || amount <= 0) {
            throw new IllegalArgumentException('Amount must be a positive, non-zero value.');
        }
        if (giftDate == null) {
            throw new IllegalArgumentException('Gift date is required.');
        }

        List<Contact> donorList = [
            SELECT Id, FirstName, LastName, AccountId
            FROM Contact
            WHERE Id = :contactId
            LIMIT 1
        ];
        if (donorList.isEmpty()) {
            throw new IllegalArgumentException('Contact does not exist: ' + contactId);
        }
        Contact donor = donorList[0];

        if (donor.AccountId == null) {
            throw new IllegalArgumentException('Contact is not associated with a Household Account.');
        }

        // All members of the household (including the donor).
        List<Contact> householdMembers = [
            SELECT Id
            FROM Contact
            WHERE AccountId = :donor.AccountId
        ];

        // 1. Create the Opportunity (gift).
        Opportunity opp = new Opportunity(
            Name = buildOpportunityName(donor, giftDate),
            AccountId = donor.AccountId,
            CloseDate = giftDate,
            StageName = STAGE_CLOSED_WON,
            Amount = amount,
            npsp__Primary_Contact__c = donor.Id
        );
        insert opp;

        // 2. Ensure exactly one Contact Role per household member, with correct roles.
        //    Remove any roles NPSP automation may have already created for this Opportunity.
        List<OpportunityContactRole> existingRoles = [
            SELECT Id
            FROM OpportunityContactRole
            WHERE OpportunityId = :opp.Id
        ];
        if (!existingRoles.isEmpty()) {
            delete existingRoles;
        }

        List<OpportunityContactRole> rolesToInsert = new List<OpportunityContactRole>();
        for (Contact member : householdMembers) {
            Boolean isDonor = (member.Id == donor.Id);
            rolesToInsert.add(new OpportunityContactRole(
                OpportunityId = opp.Id,
                ContactId = member.Id,
                Role = isDonor ? ROLE_DONOR : ROLE_HOUSEHOLD_MEMBER,
                IsPrimary = isDonor
            ));
        }
        insert rolesToInsert;

        // 3. Ensure exactly one Payment record: paid, full amount, dated giftDate.
        //    Remove any default/scheduled payment records NPSP automation may have created.
        List<npe01__OppPayment__c> existingPayments = [
            SELECT Id
            FROM npe01__OppPayment__c
            WHERE npe01__Opportunity__c = :opp.Id
        ];
        if (!existingPayments.isEmpty()) {
            delete existingPayments;
        }

        npe01__OppPayment__c payment = new npe01__OppPayment__c(
            npe01__Opportunity__c = opp.Id,
            npe01__Payment_Amount__c = amount,
            npe01__Payment_Date__c = giftDate,
            npe01__Scheduled_Date__c = giftDate,
            npe01__Paid__c = true
        );
        insert payment;

        return opp.Id;
    }

    private static String buildOpportunityName(Contact donor, Date giftDate) {
        return donor.FirstName + ' ' + donor.LastName + ' Donation ' + formatDate(giftDate);
    }

    private static String formatDate(Date d) {
        return String.valueOf(d.year())
            + '-' + padTwoDigits(d.month())
            + '-' + padTwoDigits(d.day());
    }

    private static String padTwoDigits(Integer value) {
        String s = String.valueOf(value);
        return s.length() < 2 ? '0' + s : s;
    }
}
