public with sharing class FamilyService {

    public static void linkParents(Map<Id, Id> parentIdByChildId) {
        if (parentIdByChildId == null || parentIdByChildId.isEmpty()) {
            return;
        }

        // Collect all contact ids involved so we can check existing relationships in one query
        Set<Id> allContactIds = new Set<Id>();
        allContactIds.addAll(parentIdByChildId.keySet());
        allContactIds.addAll(parentIdByChildId.values());

        // Single SOQL query: find any existing relationship touching any of these contacts
        List<npe4__Relationship__c> existingRels = [
            SELECT npe4__Contact__c, npe4__RelatedContact__c
            FROM npe4__Relationship__c
            WHERE npe4__Contact__c IN :allContactIds
               OR npe4__RelatedContact__c IN :allContactIds
        ];

        // Build a set of unordered pair keys that already have at least one relationship
        Set<String> existingPairs = new Set<String>();
        for (npe4__Relationship__c rel : existingRels) {
            existingPairs.add(pairKey(rel.npe4__Contact__c, rel.npe4__RelatedContact__c));
        }

        List<npe4__Relationship__c> toInsert = new List<npe4__Relationship__c>();

        for (Id childId : parentIdByChildId.keySet()) {
            Id parentId = parentIdByChildId.get(childId);
            if (childId == null || parentId == null) {
                continue;
            }

            String key = pairKey(childId, parentId);
            if (existingPairs.contains(key)) {
                continue; // already has a relationship in either direction, skip
            }

            // Mark as handled so duplicate pairs in the same input map don't create duplicates
            existingPairs.add(key);

            npe4__Relationship__c rel = new npe4__Relationship__c(
                npe4__Contact__c = childId,
                npe4__RelatedContact__c = parentId,
                npe4__Type__c = 'Parent',
                npe4__Status__c = 'Current'
            );
            toInsert.add(rel);
        }

        if (!toInsert.isEmpty()) {
            insert toInsert; // NPSP's own relationship trigger will create the reciprocal record
        }
    }

    private static String pairKey(Id a, Id b) {
        String idA = String.valueOf(a);
        String idB = String.valueOf(b);
        return (idA < idB) ? (idA + '_' + idB) : (idB + '_' + idA);
    }
}
