        Id oppId1 = TriggerTestUtility.getFakeId(Opportunity.SObjectType); // violates rule
        Id oppId2 = TriggerTestUtility.getFakeId(Opportunity.SObjectType); // exactly half, ok
        Id oppId3 = TriggerTestUtility.getFakeId(Opportunity.SObjectType); // increase, ok
