        };
        List<Opportunity> triggerNew = new List<Opportunity>{
            newOpp1, newOpp2, newOpp3, newOpp4, newOpp5
        };

        new TA_Opportunity_GuardAmountDecrease().beforeUpdate(triggerNew, triggerOld);

        System.assert(newOpp1.hasErrors(), 'Record 1 should have an error (reduced by more than half).');
        System.assertEquals(1, newOpp1.getErrors().size());
        System.assertEquals(
            TA_Opportunity_GuardAmountDecrease.ERROR_MESSAGE,
            newOpp1.getErrors()[0].getMessage()
        );

        System.assert(!newOpp2.hasErrors(), 'Record 2 should not have an error (reduced by exactly half).');
        System.assert(!newOpp3.hasErrors(), 'Record 3 should not have an error (increase).');
        System.assert(!newOpp4.hasErrors(), 'Record 4 should not have an error (previous Amount null).');

        System.assert(newOpp5.hasErrors(), 'Record 5 should have an error (reduced by more than half).');
        System.assertEquals(1, newOpp5.getErrors().size());
        System.assertEquals(
            TA_Opportunity_GuardAmountDecrease.ERROR_MESSAGE,
            newOpp5.getErrors()[0].getMessage()
        );
    }
