/**
 * Trigger Action (TAF 0.3.4) enforcing that two Contacts on the same Account
 * may not share the same Email address (case-insensitive comparison).
 *
 * - Contacts without an AccountId or without an Email are not checked.
 * - On update, only Contacts whose Email or AccountId changed are checked.
 * - Within a single save, the first Contact in the list "wins"; later
 *   conflicting Contacts in the same batch are rejected.
 * - Bulk-safe: at most one SOQL query per trigger execution.
 */
public inherited sharing class TA_Contact_PreventDuplicateEmail
    implements TriggerAction.BeforeInsert, TriggerAction.BeforeUpdate {
    private static final String DUPLICATE_ERROR_MESSAGE =
        'Another contact on this account already uses this email address.';

    public void beforeInsert(List<SObject> triggerNew) {
        process((List<Contact>) triggerNew, new Set<Id>());
    }

    public void beforeUpdate(List<SObject> triggerNew, List<SObject> triggerOld) {
        List<Contact> newContacts = (List<Contact>) triggerNew;
        List<Contact> oldContacts = (List<Contact>) triggerOld;
        Map<Id, Contact> oldMapById = new Map<Id, Contact>(oldContacts);

        List<Contact> toCheck = new List<Contact>();
        Set<Id> allIds = new Set<Id>();

        for (Contact newContact : newContacts) {
            allIds.add(newContact.Id);
            Contact oldContact = oldMapById.get(newContact.Id);
            if (
                newContact.Email != oldContact.Email ||
                newContact.AccountId != oldContact.AccountId
            ) {
                toCheck.add(newContact);
            }
        }

        process(toCheck, allIds);
    }

    /**
     * @param toCheck     Contacts whose Email/AccountId combination should be validated.
     * @param selfIds     Ids of Contacts in the current trigger batch (for update) that must
     *                     be excluded from the existing-records query so a record never
     *                     conflicts with itself. Empty for inserts, since new records have no Id.
     */
    private static void process(List<Contact> toCheck, Set<Id> selfIds) {
        List<Contact> relevant = new List<Contact>();
        Set<Id> accountIds = new Set<Id>();

        for (Contact c : toCheck) {
            if (c.AccountId != null && String.isNotBlank(c.Email)) {
                relevant.add(c);
                accountIds.add(c.AccountId);
            }
        }

        if (relevant.isEmpty()) {
            return;
        }

        Map<String, Id> existingKeyToId = new Map<String, Id>();
        if (!accountIds.isEmpty()) {
            for (Contact existing : [
                SELECT Id, AccountId, Email
                FROM Contact
                WHERE AccountId IN :accountIds AND Email != NULL AND Id NOT IN :selfIds
            ]) {
                existingKeyToId.put(buildKey(existing.AccountId, existing.Email), existing.Id);
            }
        }

        Set<String> seenInBatch = new Set<String>();
        for (Contact c : relevant) {
            String key = buildKey(c.AccountId, c.Email);
            if (existingKeyToId.containsKey(key) || seenInBatch.contains(key)) {
                c.addError(DUPLICATE_ERROR_MESSAGE);
            } else {
                seenInBatch.add(key);
            }
        }
    }

    private static String buildKey(Id accountId, String email) {
        return accountId + ':' + email.toLowerCase();
    }
}
