/**
 * Before-insert Trigger Action: when a new Contact has an Account and a blank LeadSource,
 * default it to the parent Account's AccountSource. Relies on TA_Contact_Queries.Service
 * having already loaded the parent Accounts earlier in the same before insert context.
 */
public with sharing class TA_Contact_DefaultLeadSource implements TriggerAction.BeforeInsert {
    public void beforeInsert(List<SObject> triggerNew) {
        Map<Id, Account> accountsById = TA_Contact_Queries.getInstance().accountsById;

        for (SObject so : triggerNew) {
            Contact c = (Contact) so;
            if (c.AccountId == null || String.isNotBlank(c.LeadSource)) {
                continue;
            }

            Account acc = accountsById.get(c.AccountId);
            if (acc == null) {
                continue;
            }

            c.LeadSource = acc.AccountSource;
        }
    }
}
